// lookup demo — Renaissance (jahdb demo program)
var DATA={"Renaissance":"The Renaissance revived classical ideals: linear perspective, anatomy, and human-centered subjects, centered in Florence and Rome."};
function lookup(q){q=String(q).toLowerCase();var h=[];for(var k in DATA){if((k+" "+DATA[k]).toLowerCase().indexOf(q)>=0)h.push(k+": "+DATA[k]);}return h.length?h.join("\n"):"no match for "+q;}
function listAll(){return Object.keys(DATA).join(", ");}
console.log("sample lookup:");console.log(lookup("c. 1400-1520"));

